#include "ark/onboarding.hpp"
#include <stdexcept>
namespace ark {
arkjson::Value agentOnboard(const AgentSession& session,const arkjson::Value& args){
    using V=arkjson::Value;std::string topic="overview";
    if(auto p=args.find("topic")){if(p->t!=V::Str)throw std::runtime_error("topic must be a string");topic=p->str;}
    if(topic!="overview"&&topic!="sketch"&&topic!="tube"&&topic!="assembly"&&topic!="surfacing"&&topic!="sheet"&&topic!="solids")throw std::runtime_error("Unknown onboarding topic; choose overview, sketch, tube, assembly, surfacing, sheet or solids");
    V r=V::makeObj();r.set("product",V::makeStr("ARK"));r.set("name",V::makeStr("Agent-Ready Kernel"));r.set("tagline",V::makeStr("Parametric CAD for people and agents."));r.set("version",V::makeStr("0.9.0"));r.set("topic",V::makeStr(topic));r.set("document",session.info());
    r.set("units",V::makeStr("Lengths mm; plane/feature rotations degrees; sketch angle constraints and trig radians. deg(x) converts degrees to radians."));
    auto list=[](std::initializer_list<const char*> strings){V a=V::makeArr();for(auto s:strings)a.arr.push_back(V::makeStr(s));return a;};
    r.set("workflow",list({"Read this onboarding then doc_get only when detailed parameters/features are needed.","Use doc_apply with expected_revision. One batch recomputes once; any failure rolls back the entire batch.","Use created_ids returned by a batch for later feature inputs. Do not assume IDs or use triangle IDs as persistent references.","Inspect native B-rep validation evidence with native_inspect and source inventory with step_inspect; mesh_inspect and raycast see display tessellation.","Keep queries compact; request meshes or snapshots only when needed. Save the parametric document with doc_save."}));
    r.set("available_topics",list({"overview","sketch","tube","assembly","surfacing","sheet","solids"}));
    r.set("boundaries",list({"OCCT 8.0.1 native solids, loft, fill, NURBS, thicken and supported sheet operations produce exact B-reps with explicit validity reports. The viewport mesh and mesh_inspect are display evidence, not exact solid authority; per-face triangulations can have boundary edges.","Legacy sampled mesh operations remain separate. Exact B-reps use supported native_solid operations; unsupported approximate downstream operations reject rather than silently tessellating exact geometry.","Source STEP tube and sheet features are read-only, bounded recognition/projection domains. General arbitrary STEP feature-history reconstruction is unavailable.","Producer-authored semantic references and assembly mates are supported, but arbitrary topology naming, global sketch uniqueness, assembly collision clearance and manufacturing qualification are not established. GPU acceleration applies to packed transforms/display, not every CAD operation."}));
    r.set("capabilities",list({"Named parameters and expression dependencies","Named construction planes with parent and supported exact reference frames","Dimensioned sketches: points, lines, circles, interpolating splines, with read-only conflict diagnosis","Exact native OCCT solid operations, loft, boundary fill, B-spline surface and thickening","Authored sheet panel/flange graph and bounded original STEP sheet import","Native STEP export and source-preserving tube projection without Python runtime","Legacy mesh features and grounded assembly mates, with explicit native/mesh boundary","Atomic edits, undo/redo, versioned native document persistence, exact and mesh inspection"}));
    if(topic=="sketch"){
        r.set("tools",list({"doc_apply","plane_inspect","reference_inspect","sketch_inspect","sketch_diagnose","mesh_inspect","mesh_raycast","snapshot","doc_save"}));
        r.set("rules",list({"plane.set{name,kind:plane|axis|frame,parent,p:{ox,oy,oz,rx,ry,rz}} creates/updates a named datum. support:{kind:face|midplane|normal_to_curve|tube_path,feature,reference,second_reference?,second_feature?,fraction?,station?} attaches it to authored geometry. Inspect semantic names with reference_inspect. Built-in XY/XZ/YZ cannot be changed. XZ normal=-Y, YZ normal=+X.","sketch.set{name,sketch:{plane,tolerance,entities,constraints}} replaces a sketch. Names identify sketches and entities; changing a referenced name is not an automatic rename.","Entity kind is point|line|circle|spline. dof is [x,y], [x0,y0,x1,y1], [cx,cy,r] or flattened spline anchors. construction:true excludes an entity from solid profiles.","A string coordinate such as 'width/2' is driven exactly by that expression. A numeric coordinate is a free solver variable/initial position. Constraint val/val2 accept numeric values or expressions.","Spline: 2..64 anchors (closed minimum 3), closed:true wraps without repeating first anchor; tension 0..1. Centripetal Catmull-Rom converts to cubic Bezier controls. Legacy profile/display consumers sample to sketch tolerance; native surfacing carries the Bezier spans as exact edges. Sketch tolerance is not manufacturing accuracy.","sketch.entity.set{name,entity:{name,kind,dof,...}} replaces/appends one named entity. Unchanged entities and constraint indexes stay in place. Use it to avoid resending an entire sketch.","Constraint types: fixedX, fixedY, fixed, distance, horizontal, vertical, parallel, perpendicular, radius, coincident, angle. a/b index entities; pa/pb index line endpoints or spline anchors; circle slot0=center.","Extrude/revolve consumes one closed outer loop via p.sketch. sketch_cut consumes one base feature in inputs and one sketch of disjoint closed loops, with p.depth positive and p.offset along local normal.","Open curves can be saved/inspected but cannot form a solid until explicitly closed. Self-crossing/touching sampled profiles, nested loops and ambiguous joins are rejected.","sketch_inspect reports resolved coordinates, remaining_dofs, local Jacobian rank and profile_ready. Underconstrained does not mean failed. samples:true adds local/world polylines.","Limits: 64 sketches, 128 entities and 256 constraints per sketch, 512 scalar coordinates, 2048 samples per curve/loop and 4096 per profile collection. Tolerance 0.0001..5 mm."}));
        V example;arkjson::parse(R"({"commands":[{"op":"param.set","name":"width","expr":"100"},{"op":"param.set","name":"height","expr":"45"},{"op":"plane.set","name":"design","parent":"XY","p":{"oz":"8","rx":"15"}},{"op":"sketch.set","name":"outline","sketch":{"plane":"design","tolerance":0.03,"entities":[{"name":"skin","kind":"spline","closed":true,"dof":["-width/2","0","-width/3","-height/2","width/3","-height/2","width/2","0","width/3","height/2","-width/3","height/2"]}]}},{"op":"feature.add","type":"extrude","name":"Freeform plate","p":{"sketch":"outline","height":"6"}}]})",example);
        example.set("expected_revision",V::makeNum((double)session.revision));r.set("example_doc_apply",example);
        r.set("next_step",V::makeStr("After this example, inspect outline, then change width with param.set. To cut holes, create a circle sketch on design and sketch_cut with the returned extrusion ID, depth='8', offset='-1'."));
    }else if(topic=="tube"){
        r.set("tools",list({"import_step","source_inspect","notch_plan","notch_inspect","tube_inspect","export_step"}));
        r.set("rules",list({"import_step{path,replace:false} adds a supported source tube without replacing the current document. replace:true replaces it. Source stays read-only.","source_inspect{id,progress} reads source/flat openings and evidence; progress 0..1 is display only. Export STEP is always straight.","Designed notched_tube uses dimensions width_mm,height_mm,wall_mm,length_mm,hinge_offset_mm plus notches:[{station,angle,face}]. This ideal model differs from finite source hinges.","Tube programs use round/rect sections and bends [{feed,radius,angle,roll}]. Tube program previews and imported-source validation have different guarantees.","Use existing source geometry as the authority for hole locations. Never infer missing source features from a screenshot or silently invent unsupported deformation."}));
    }else if(topic=="surfacing"){
        r.set("tools",list({"doc_apply","sketch_inspect","native_inspect","mesh_inspect","export_step","kernel_info","doc_save"}));
        r.set("rules",list({"loft uses native:{sections:[sketch names]} and p:{solid:0|1,ruled:0|1,max_degree?:1..8}. Sections need the same explicit connected edge topology; solid sections must be closed. Named sketch planes provide section frames.","Sketch lines and circles become native analytic edges. Interpolating spline spans become their exact cubic Bezier control segments, not sampled polylines. Construction entities are excluded.","surface_fill consumes p:{sketch:name} or native:{profile:{frame:[16],entities:[ordered line/circle/bezier boundaries]}}. Boundaries must be explicitly connected and closed; filling is C0 and rejects a boundary residual beyond 1e-6 mm.","bspline_surface consumes native:{poles:rows of [x,y,z],weights?:matching positive grid} and p:{u_degree,v_degree}. Its clamped uniform knots and degrees 1..8 require enough poles. Pole and weight coordinates accept parameter expressions.","thicken consumes one native face/shell feature ID in inputs and p:{thickness} signed and nonzero. It must yield one validated positive-volume solid; it does not certify self-intersection absence or physical manufacturability.","native_inspect reports OCCT B-rep validation and construction evidence compactly. mesh_inspect reports the f32 display tessellation; an open surface or per-face mesh can have boundary edges without implying a failed B-rep.","export_step writes the exact B-rep through a C++ OCCT worker and reads STEP back. Native exact bodies cannot flow into legacy mesh transform/Boolean/pattern/sketch_cut operations."}));
        V example;arkjson::parse(R"({"commands":[{"op":"param.set","name":"base_radius","expr":"5"},{"op":"param.set","name":"rise","expr":"10"},{"op":"plane.set","name":"upper","p":{"oz":"rise"}},{"op":"sketch.set","name":"lower_circle","sketch":{"entities":[{"kind":"circle","dof":[0,0,"base_radius"]}]}},{"op":"sketch.set","name":"upper_circle","sketch":{"plane":"upper","entities":[{"kind":"circle","dof":[0,0,3]}]}},{"op":"feature.add","type":"loft","name":"Native ruled frustum","p":{"solid":1,"ruled":1},"native":{"sections":["lower_circle","upper_circle"]}}]})",example);
        example.set("expected_revision",V::makeNum((double)session.revision));r.set("example_doc_apply",example);
        r.set("next_step",V::makeStr("Run the example batch, then native_inspect the created ID. Edit rise or base_radius and inspect again; export_step writes the exact B-rep."));
    }else if(topic=="solids"){
        r.set("tools",list({"doc_apply","reference_inspect","plane_inspect","native_inspect","export_step","doc_save"}));
        r.set("rules",list({"feature.add type native_solid stores native.op and numeric expressions in p. Exact primitives: box{width,depth,height}, cylinder{radius,height}, sphere{radius}, cone{radius_bottom,radius_top,height}, torus{major_radius,minor_radius}.","Native extrude uses p:{sketch,depth}; line/circle and spline-derived cubic Bezier edges stay exact. union/cut/common take two earlier inputs. transform takes one input and p:{tx,ty,tz,rx,ry,rz} or native.frame[16] column-major rigid matrix.","hole takes one input plus native.cutter:{kind:circle|slot|profile,plane,cx?,cy?,offset?,depth,radius?|length,width}. Profile cutters use p.sketch. Positive depth follows the plane normal; offset can start the cut below its support. A blind depth makes a pocket; a depth crossing the whole body makes a through-cut.","fillet/chamfer take one input, native.edges:[semantic edge names], and p.radius or p.distance. Discover names via reference_inspect. Existing mesh primitives can be promoted from their analytic authoring parameters; display triangles never become the authority.","Reference registries bind to the current B-rep digest. OCCT operation history preserves unique face/edge bindings; split/deleted/ambiguous references reject. Boolean tool references use tool.<feature id> namespaces. Some curved faces have stable identity but no unique rigid frame (frame_available:false).", "STEP uses the exact B-rep and independent readback checks. Valid solid/volume checks do not certify all self-intersections, tool access, mechanics or manufacturing."}));
        r.set("next_step",V::makeStr("Create a native primitive or extrude an authored sketch. Discover semantic references, attach a datum and hole, change a dimension, inspect the rebuilt B-rep, then export STEP."));    }else if(topic=="sheet"){
        r.set("tools",list({"doc_apply","sheet_preview","step_inspect","import_sheet_step","native_inspect","export_step","kernel_info","doc_save"}));
        r.set("rules",list({"sheet.create{name,p:{width,thickness,k_factor},base:{id,length}} creates a rectangular base. sheet.flange.add{id,flange:{id?,parent,edge,length,width?,offset?,inner_radius,angle,k_factor?}} adds an explicitly attached flange. Up to 16 flanges; signed angles 0.001..169.999 degrees; unique panel IDs and earlier parents.","sheet.flange.edit/id/entity/values and sheet.opening.edit/id/entity/values preserve identity. Removal with dependants requires explicit cascade:true. Legacy L-bend p:{width,leg_a,leg_b,thickness,inner_radius,angle,k_factor} remains supported and promotes when edited with graph commands.","sheet.opening.add{id,opening:{id?,panel,kind:circle|polygon,x,y,radius,points}} binds a real cut to a named panel. Local expressions panel_length/panel_width/thickness preserve design intent. Flange expressions also expose parent_length/parent_width/edge_length. Legacy numeric panel 0/1 remains supported. Edge/bend-crossing openings reject.","The native result carries formed and flat B-reps and meshes, a declared geometric bend allowance and an explicit K-dependent formed/flat volume difference. K=0.5 gives the midpoint geometric volume model; other K values do not claim material conservation.","step_inspect inventories an original STEP independently. import_sheet_step{path,k_factor,body_index?,root_panel?,replace?} then imports one supported exact body as read-only source_sheet. Multiple bodies require body_index; an equally plausible root-panel tie requires root_panel 0 or 1.","Original STEP sheet import supports a single flat panel or two constant-width rigid panels joined by one complete cylindrical bend, with owned rigid-panel openings. Curved-zone cuts, segmented or multiple bends and ambiguous source topology reject.","native_inspect returns source hash, body, bend/opening census, measured flat length, and source/refold evidence without B-rep buffers. Source report source_projection_verified is geometric proof, not manufacturing qualification.","Authored panel trees validate analytic integrals, flat/formed interference and an independent neutral-line refold by whole-solid difference. sheet_preview{id,progress} returns display-only sequential panel poses; motion trajectory and press-tool collision are not certified.","export_step defaults to flat for sheet features; pose:formed writes the formed B-rep. Imported-source export rebinds source bytes when present and the verified embedded payload for portable documents. Changed existing source bytes reject."}));
        V example;arkjson::parse(R"({"commands":[{"op":"feature.add","type":"sheet_metal","name":"Two-flange sample","p":{"width":60,"leg_a":80,"leg_b":50,"thickness":2,"inner_radius":5,"angle":90,"k_factor":0.5},"native":{"openings":[{"panel":0,"kind":"circle","x":25,"y":20,"radius":4},{"panel":1,"kind":"polygon","points":[[15,20],[25,20],[25,30],[15,30]]}]}}]})",example);
        example.set("expected_revision",V::makeNum((double)session.revision));r.set("example_doc_apply",example);
        r.set("next_step",V::makeStr("Run the designed-sheet example and native_inspect the created ID. Use export_step for flat or pose:formed; inspect an original STEP before a separate import_sheet_step."));
    }else if(topic=="assembly"){
        r.set("tools",list({"doc_apply","reference_inspect","assembly_info","mesh_inspect","mesh_raycast","doc_save"}));
        r.set("rules",list({"assembly.add{name,parent,feature,p,visible,fixed}: parent=0 root, feature=0 group, otherwise existing feature ID. fixed:true grounds a part instance at its authored placement.","p is rigid tx/ty/tz/rx/ry/rz expressions relative to parent. Shared feature definitions produce instances, not duplicated geometry.","mate.add{a,b,type,reference_a,reference_b,value?,fraction_a?,fraction_b?}, mate.edit{id,...}, mate.remove{id}. Endpoints are direct sibling part instance IDs. Each mate-connected component needs a fixed instance.","Mate types: concentric aligns axes; coincident aligns origins and +Z; contact opposes +Z normals with zero plane gap; distance measures signed mm along A +Z; angle measures 0..180 degrees between +Z axes.","Local references origin/X/Y/Z/XY are available. For exact semantic face, edge and axis references, discover producer-authored names with reference_inspect{id}; stale, split or deleted references reject.","assembly_info returns solved world matrices, BOM, mate definitions and diagnostics: position/angle residuals, local Jacobian rank, remaining DOFs and unconstrained instances. A successful underconstrained solve keeps authored placement for free coordinates.","Mates place instances but do not fuse bodies or certify collisions and motion clearance. Mesh queries accept node for an instance or id for a part definition, never both."}));
        r.set("next_step",V::makeStr("Inspect the current assembly and exact reference names, ground one part instance, then add sibling mates in a single revision-checked doc_apply batch. Read assembly_info diagnostics after the solve."));
    }else r.set("next_step",V::makeStr("Choose sketch, solids, surfacing, sheet, tube or assembly for a targeted contract. No language model or Python runtime is required for deterministic native geometry operations."));
    return r;
}
}
